//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_text::markdown::{
    arena::NodeId,
    block_reader::BlockReader,
    context::{Context, NodeKind},
    text::Segment,
};
use serde::Deserialize;
use serde_json::{Value, json};
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Call {
    kind: String,
    advance: isize,
}
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Request {
    source: String,
    segments: Vec<Segment>,
    calls: Vec<Call>,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Request>,
    results: Vec<Value>,
}
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}
fn snapshot(c: &Context, r: &mut BlockReader<'_>, returned: Option<NodeId>) -> Value {
    let text = r.peek_line().0.map(|b| hex(&b.bytes()));
    let (line, pos) = r.position();
    json!({"nodes":c.arena.nodes(),"first_delimiter":c.first_delimiter,"last_delimiter":c.last_delimiter,"returned":returned,"line":line,"position":pos,"text":text,"source":hex(&r.source().bytes())})
}
#[test]
fn pinned_goldmark_inline_delimiter_parsers() {
    let f: Fixture = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/inline-delimiter.json"
    ))
    .unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (i, (q, expected)) in f.requests.into_iter().zip(f.results).enumerate() {
        let source: Vec<_> = (0..q.source.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&q.source[i..i + 2], 16).unwrap())
            .collect();
        let mut r = BlockReader::new(&source, Some(&q.segments));
        let mut c = Context::default();
        let root = c.arena.insert(NodeKind::Container);
        let mut snapshots = vec![snapshot(&c, &mut r, None)];
        for call in q.calls {
            r.advance(call.advance);
            let returned = if call.kind == "strike" {
                c.parse_strikethrough(&mut r)
            } else {
                c.parse_emphasis(&mut r)
            };
            if let Some(node) = returned {
                c.arena.append_child(root, node);
            }
            snapshots.push(snapshot(&c, &mut r, returned));
        }
        assert_eq!(json!(snapshots), expected, "case {i}");
    }
}
